        if (ctDrawing.sizeOfTwoCellAnchorArray() <= 0) {
            return;
        }
        List<CTTwoCellAnchor> alist = ctDrawing.getTwoCellAnchorList();
        for (int j = 0; j < alist.size(); j++) {
